def build_agent(sandbox):
    # Single-beam amphibian with optimized buoyancy and thrust efficiency
    beam = sandbox.add_beam(x=5.0, y=2.0, width=1.5, height=0.5, density=300.0)
    sandbox.set_material_properties(beam, restitution=0.05)
    return beam

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x()
    target_x = 26.0

    # Stop if target is reached
    if front_x >= target_x:
        return

    # Apply force every 4 steps (3-step cooldown)
    if step_count % 4 != 0:
        return

    vx = agent_body.linearVelocity.x
    THRUST_F = 520.0  # Max allowed thrust per component

    # Adaptive thrust based on environment (land/water)
    in_water = front_x >= 10.0

    if in_water:
        # Water phase: moderate thrust to avoid speed cap
        if vx > 3.5:
            fx = THRUST_F * 0.1
        elif vx > 1.0:
            fx = THRUST_F * 0.4
        else:
            fx = THRUST_F * 0.7  # Conservative thrust in water
    else:
        # Land phase: full thrust for rapid acceleration
        fx = THRUST_F

    # Apply forward thrust
    sandbox.apply_force(agent_body, fx, 0.0, step_count=step_count)
